// Demo diary: five days with different moods, so the archive can be checked
// as a series right away. Photos were generated by a free image model
// (Pollinations) without people's faces; songs are 30-second Apple Music
// previews streamed from Apple. Procedural photos remain as an offline fallback.

import { db } from './db.js';
import { createDay } from './pipeline.js';
import { DEMO_DATA } from './demo-data.js';
import { fetchPreview } from './music.js';

function rnd(seed) {
  let a = seed;
  return () => { a = (a * 1664525 + 1013904223) >>> 0; return a / 4294967296; };
}
function cvs(w = 900, h = 1125) { const c = document.createElement('canvas'); c.width = w; c.height = h; return [c, c.getContext('2d')]; }
const toBlob = c => new Promise(r => c.toBlob(r, 'image/jpeg', 0.9));
function lin(ctx, h, stops) { const g = ctx.createLinearGradient(0, 0, 0, h); stops.forEach(([o, c]) => g.addColorStop(o, c)); return g; }
function glow(ctx, x, y, r, color) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color); g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function autumnPark(v) {
  const [c, ctx] = cvs(); const r = rnd(11 + v);
  ctx.fillStyle = lin(ctx, 1125, [[0, '#cfd6d6'], [0.45, '#efe3cc'], [0.55, '#c9a46a'], [1, '#8a6232']]);
  ctx.fillRect(0, 0, 900, 1125);
  if (v === 1) { ctx.fillStyle = 'rgba(120,140,150,.55)'; ctx.beginPath(); ctx.ellipse(450, 760, 420, 90, 0, 0, Math.PI * 2); ctx.fill(); }
  for (let i = 0; i < 9; i++) {
    const x = r() * 900; ctx.strokeStyle = '#3d2a1c'; ctx.lineWidth = 10 + r() * 14;
    ctx.beginPath(); ctx.moveTo(x, 640 + r() * 60); ctx.lineTo(x + (r() - .5) * 40, 260); ctx.stroke();
  }
  ctx.filter = 'blur(6px)';
  for (let i = 0; i < 260; i++) {
    const cols = ['#e8a33b', '#d9822b', '#f2c14e', '#b8612a', '#f0d48a'];
    ctx.fillStyle = cols[Math.floor(r() * cols.length)];
    ctx.globalAlpha = .55 + r() * .4;
    ctx.beginPath(); ctx.arc(r() * 900, 120 + r() * 460, 18 + r() * 46, 0, Math.PI * 2); ctx.fill();
  }
  for (let i = 0; i < 220; i++) {
    ctx.fillStyle = ['#d98a2b', '#f2b544', '#a8562a'][i % 3];
    ctx.beginPath(); ctx.ellipse(r() * 900, 820 + r() * 300, 10 + r() * 10, 5, r() * 3, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1; ctx.filter = 'none';
  if (v === 2) { // two cups of cocoa
    ctx.filter = 'blur(2px)';
    [[360, '#f3ece2'], [540, '#e8dccd']].forEach(([x, col]) => {
      ctx.fillStyle = col; ctx.fillRect(x - 60, 760, 120, 150);
      ctx.fillStyle = '#6b3f22'; ctx.beginPath(); ctx.ellipse(x, 762, 60, 16, 0, 0, Math.PI * 2); ctx.fill();
    });
    ctx.filter = 'none';
  }
  glow(ctx, 700, 260, 380, 'rgba(255,230,180,.55)');
  return toBlob(c);
}

function officeNight(v) {
  const [c, ctx] = cvs(); const r = rnd(31 + v);
  ctx.fillStyle = lin(ctx, 1125, [[0, '#0b1220'], [1, '#18222f']]); ctx.fillRect(0, 0, 900, 1125);
  for (let x = 0; x < 900; x += 150) { ctx.fillStyle = '#05080e'; ctx.fillRect(x, 0, 10, 700); }
  ctx.fillRect(0, 690, 900, 12);
  for (let i = 0; i < 140; i++) { ctx.fillStyle = r() > .6 ? 'rgba(255,220,150,.8)' : 'rgba(150,190,255,.6)'; ctx.fillRect(r() * 900, 380 + r() * 300, 6, 9); }
  ctx.fillStyle = '#0a0f17'; ctx.fillRect(0, 700, 900, 425);
  const mx = v ? 260 : 120;
  glow(ctx, mx + 230, 760, 420, 'rgba(120,180,255,.35)');
  ctx.fillStyle = '#cfe2ff'; ctx.fillRect(mx, 640, 460, 270);
  ctx.fillStyle = '#1b2738';
  for (let i = 0; i < 9; i++) ctx.fillRect(mx + 30, 670 + i * 25, 120 + r() * 280, 8);
  ctx.fillStyle = '#05080e'; ctx.fillRect(mx + 200, 910, 60, 60); ctx.fillRect(mx + 120, 960, 220, 14);
  if (v) { ctx.fillStyle = '#e7e2d8'; ctx.fillRect(140, 900, 70, 90); glow(ctx, 175, 880, 90, 'rgba(255,255,255,.2)'); }
  return toBlob(c);
}

function concert(v) {
  const [c, ctx] = cvs(); const r = rnd(51 + v);
  ctx.fillStyle = '#120a16'; ctx.fillRect(0, 0, 900, 1125);
  ctx.globalCompositeOperation = 'lighter';
  const cols = ['rgba(255,80,120,.35)', 'rgba(255,190,60,.35)', 'rgba(60,200,255,.3)', 'rgba(255,120,40,.35)'];
  for (let i = 0; i < 7; i++) {
    const x = 120 + r() * 660; ctx.fillStyle = cols[i % cols.length];
    ctx.beginPath(); ctx.moveTo(x, 80); ctx.lineTo(x - 260 - r() * 200, 1125); ctx.lineTo(x + 160 + r() * 200, 1125); ctx.closePath(); ctx.fill();
  }
  for (let i = 0; i < 40; i++) glow(ctx, r() * 900, 60 + r() * 200, 30 + r() * 50, cols[i % 4]);
  ctx.globalCompositeOperation = 'source-over';
  ctx.strokeStyle = 'rgba(255,255,255,.25)'; ctx.lineWidth = 2;
  for (let i = 0; i < 120; i++) { const x = r() * 900, y = r() * 900; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 8, y + 34); ctx.stroke(); }
  ctx.fillStyle = '#07040a';
  for (let i = 0; i < 26; i++) {
    const x = r() * 900, y = 860 + r() * 140, s = 50 + r() * 40;
    ctx.beginPath(); ctx.arc(x, y, s * .45, 0, Math.PI * 2); ctx.fill(); ctx.fillRect(x - s * .6, y + s * .3, s * 1.2, 400);
    if (r() > .7) { ctx.lineWidth = 16; ctx.strokeStyle = '#07040a'; ctx.beginPath(); ctx.moveTo(x, y + 40); ctx.lineTo(x + 30 * (r() - .5), y - 120); ctx.stroke(); }
  }
  return toBlob(c);
}

function rainyWindow(v) {
  const [c, ctx] = cvs(); const r = rnd(71 + v);
  ctx.fillStyle = lin(ctx, 1125, [[0, '#8e979c'], [1, '#5f676c']]); ctx.fillRect(0, 0, 900, 1125);
  ctx.filter = 'blur(18px)';
  for (let i = 0; i < 12; i++) { ctx.fillStyle = `rgba(${60 + r() * 40},${70 + r() * 40},${75 + r() * 40},.8)`; ctx.fillRect(r() * 900, 200 + r() * 600, 120 + r() * 200, 300 + r() * 400); }
  ctx.filter = 'none';
  glow(ctx, v ? 680 : 220, 820, 260, 'rgba(255,190,120,.55)');
  for (let i = 0; i < 380; i++) {
    const x = r() * 900, y = r() * 1125, s = 2 + r() * 7;
    ctx.fillStyle = 'rgba(230,236,240,.35)'; ctx.beginPath(); ctx.arc(x, y, s, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(40,46,50,.3)'; ctx.beginPath(); ctx.arc(x + s * .3, y + s * .3, s * .6, 0, Math.PI * 2); ctx.fill();
  }
  ctx.fillStyle = '#3f4448'; ctx.fillRect(0, 540, 900, 14); ctx.fillRect(440, 0, 14, 1125);
  return toBlob(c);
}

function balconyMorning() {
  const [c, ctx] = cvs(); const r = rnd(91);
  ctx.fillStyle = lin(ctx, 1125, [[0, '#dfe7ee'], [0.6, '#f6e7da'], [1, '#e9d7c6']]); ctx.fillRect(0, 0, 900, 1125);
  glow(ctx, 640, 520, 300, 'rgba(255,214,170,.7)');
  ctx.fillStyle = 'rgba(150,160,175,.55)';
  for (let x = 0; x < 900; x += 40 + r() * 50) { const h = 120 + r() * 260; ctx.fillRect(x, 720 - h, 34 + r() * 40, h); }
  ctx.fillStyle = 'rgba(110,118,130,.7)';
  for (let x = 0; x < 900; x += 60 + r() * 60) { const h = 60 + r() * 160; ctx.fillRect(x, 760 - h, 50 + r() * 50, h + 40); }
  ctx.fillStyle = '#d9cfc4'; ctx.fillRect(0, 800, 900, 325);
  ctx.fillStyle = '#4b4743';
  for (let x = 20; x < 900; x += 70) ctx.fillRect(x, 800, 8, 200);
  ctx.fillRect(0, 795, 900, 10);
  ctx.fillStyle = '#f4f1ec'; ctx.fillRect(560, 900, 110, 120);
  ctx.fillStyle = '#9a6b3e'; ctx.beginPath(); ctx.ellipse(615, 902, 55, 14, 0, 0, Math.PI * 2); ctx.fill();
  return toBlob(c);
}


async function demoPhotos(n, fallback) {
  try {
    const blobs = await Promise.all(['a', 'b'].map(async v => {
      const r = await fetch(`assets/demo/d${n}${v}.jpg`);
      if (!r.ok) throw new Error('missing');
      return r.blob();
    }));
    return blobs;
  } catch { return fallback(); }
}


export const DEMO_DAYS = [
  {
    date: '2026-10-18', number: 1,
    text: 'Гуляли с подругой по парку, всё в жёлтых листьях. Было холодно, но мы пили какао и долго разговаривали. Я давно не была такой спокойной. Солнце садилось низко, и всё вокруг было тёплым и медленным.',
    photos: () => demoPhotos(1, () => Promise.all([autumnPark(0), autumnPark(2)])),
    genre: 'jazz', extras: { timeOfDay: 'evening' },
  },
  {
    date: '2026-11-12', number: 2,
    text: 'Срочная сдача проекта, ночь в офисе. Я сидел один, в наушниках электроника, третий кофе, нервы на пределе. Дедлайн в шесть утра, всё время спешка и напряжение.',
    photos: () => demoPhotos(2, () => Promise.all([officeNight(0), officeNight(1)])),
    genre: 'electronic', extras: { timeOfDay: 'night' },
  },
  {
    date: '2026-08-23', number: 3,
    text: 'Концерт с друзьями под дождём! Танцевали, кричали песни, я промок насквозь, и это было лучшее лето. Громко, весело, ура!',
    photos: () => demoPhotos(3, () => Promise.all([concert(0), concert(1)])),
    genre: 'rock', extras: { timeOfDay: 'evening', weather: 'rain' },
  },
  {
    date: '2026-09-27', number: 4,
    text: 'Весь день дождь. Сидела дома одна, смотрела в окно и вспоминала бабушку. Грустно и пусто, но почему-то спокойно.',
    photos: () => demoPhotos(4, () => Promise.all([rainyWindow(0), rainyWindow(1)])),
    genre: 'indie', extras: { weather: 'rain' },
  },
  {
    date: '2026-11-16', number: 5,
    text: 'Утро на балконе. Чай, город ещё не проснулся, на улице ни звука. Ничего особенного не происходило, я просто смотрел на небо и дома напротив.',
    photos: () => demoPhotos(5, () => Promise.all([balconyMorning()])),
    genre: 'ambient', extras: { timeOfDay: 'morning' },
  },
];

export async function seedIfEmpty(force = false, onProgress = () => {}) {
  const seeded = await db.getMeta('seeded-v6');
  if (seeded && !force) return false;
  let i = 0;
  for (const d of DEMO_DAYS) {
    onProgress(++i, DEMO_DAYS.length);
    const { ai, track } = DEMO_DATA[d.number];
    let file = null;
    try { file = await fetchPreview(track); } catch (e) { console.warn('preview', e); }
    const song = { kind: 'track', track, file, fileName: file ? `${track.artist} - ${track.title}.m4a` : '', meta: { artist: track.artist, title: track.title, genre: d.genre, year: track.year } };
    await createDay({ ...d, id: 'demo-' + d.number, photos: await d.photos(), song, ai, demo: true });
  }
  await db.setMeta('seeded-v6', true);
  return true;
}
